sys_script.script:
(function executeRule(current, previous /*null when async*/) {
  /* I34: a closed engagement must not accumulate attachments.

     Why this is an AFTER rule that deletes, rather than a BEFORE rule that
     refuses: current.setAbortAction(true) DOES NOT STOP an attachment insert -
     ServiceNow's attachment writer ignores it (proven by instrumenting the rule;
     it fired and the file landed anyway). And GlideRecord.deleteRecord() returns
     false here, because a scoped app has no delete privilege on sys_attachment.
     GlideSysAttachment().deleteAttachment() is the sanctioned path.

     So this is a compensating control, not refusal: the row exists briefly and is
     then removed. It holds on every write path including the browser REST upload
     the portal uses. Staff are exempt so PTAG can still attach from the workspace. */
  if (String(current.getValue('table_name')) !== 'x_snc_ptag_engage_engagement_request') {
    return;
  }
  var t = {};
  try {
    var acc = new x_snc_ptag_engage.PTAGHubAccess();
    if (acc.isStaff()) { return; }
    var gr = new GlideRecord('x_snc_ptag_engage_engagement_request');
    if (!gr.get(String(current.getValue('table_sys_id')))) { return; }
    if (!acc.isAttachLocked(gr.getValue('state'))) { return; }

    var id = current.getUniqueValue();
    new GlideSysAttachment().deleteAttachment(id);

    var chk = new GlideRecord('sys_attachment');
    t.gone = !chk.get(id);
    t.id = String(id);
    try { gs.getUser().savePreference('ptag.hub.i34g_trace', JSON.stringify(t)); } catch (e1) {}
    gs.addErrorMessage('This engagement is closed and can no longer accept attachments.');
  } catch (e) {
    t.err = String(e).substring(0, 200);
    try { gs.getUser().savePreference('ptag.hub.i34g_trace', JSON.stringify(t)); } catch (e2) {}
  }
})(current, previous);
